css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; }
.dcx a[style*="inline-flex"]{ white-space: nowrap; }
.dcx img{ max-width: 100%; height: auto; }
@media (prefers-reduced-motion: reduce){.dcx *,.dcx *::before,.dcx *::after{ animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; scroll-behavior: auto !important; }
}
.dcx a{ color: #0B7A45; text-decoration: none; }
.dcx a:hover{ color: #0A6A3C; }
.dcx :focus-visible{ outline: 2px solid #0FA45B; outline-offset: 3px; }
.dcx [data-mega]{ display: none; }
.dcx [data-navitem]:hover [data-mega],.dcx [data-mega]:hover{ display: block; }
.dcx [data-burger]{ display: none; }
@media (max-width: 1100px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-burger]{ display: inline-flex !important; }
.dcx [data-two],.dcx [data-three],.dcx [data-four],.dcx [data-dark]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-rail]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-rail] > div{ border-left: 0 !important; }
.dcx [data-h1]{ font-size: 38px !important; }
.dcx [data-h2]{ font-size: 30px !important; }
.dcx [data-hand]{ display: none !important; }
}
@media (max-width: 640px){.dcx [data-rail],.dcx [data-stats],.dcx [data-herostats]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-h1]{ font-size: 31px !important; }
.dcx [data-pad]{ padding-left: 20px !important; padding-right: 20px !important; }
}
.dch-5490d8da:focus{left: 12px !important;top: 12px !important}
.dch-eb6ba876:hover{background: #0B8A4B !important;color: #fff !important}
.dch-119534d8:hover{background: #F4F7F2 !important;color: #08120D !important}
@media (min-width: 1101px){.dcx{ zoom: 1; }
}
.dcx #rl-hero{ aspect-ratio: 1312 / 1199 !important; height: auto !important; }
@media (max-width: 1100px){.dcx main > section:first-child > [data-two]{ padding: 0 28px 40px !important; gap: 12px !important; }
.dcx #rl-hero{ width: min(100%, 640px) !important; justify-self: center; border-radius: 22px; overflow: hidden; }
}
@media (max-width: 640px){.dcx main > section:first-child > [data-two]{ padding: 0 20px 32px !important; }
.dcx #rl-hero{ border-radius: 16px; }
.dcx [data-herostats]{ row-gap: 20px !important; }
.dcx [data-herostats] > li:nth-child(3){ padding-left: 0 !important; border-left: 0 !important; }
}
